    """
    Sorts an array of integers using the QuickSort algorithm.

    Parameters:
    arr (list): The input list to be sorted.

    Returns:
    list: A new list containing the sorted elements.
    """
    if len(arr) <= 1:
        return arr
    else:
        pivot = arr[0]  # Selecting the first element from the list

        less_than_pivot = []  # List to store all elements less than the pivot
        greater_than_pivot = []  # List to store all elements greater than the pivot

        for num in arr:
            if num < pivot:
                less_than_pivot.append(num)
            elif num > pivot:
                greater_than_pivot.append(num)

        return quicksort(less_than_pivot) + [pivot] + quicksort(greater_than_pivot)

